sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float height;
uniform float ambient;
uniform float shine;
layout(color) uniform half4 light;
float lum(float2 at) {
    half4 c = image.eval(at);
    return c.a > 0.0 ? dot(float3(c.rgb), float3(0.2126, 0.7152, 0.0722)) : 0.0;
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float dx = lum(coord + float2(1.0, 0.0)) - lum(coord - float2(1.0, 0.0));
    float dy = lum(coord + float2(0.0, 1.0)) - lum(coord - float2(0.0, 1.0));
    float3 n = normalize(float3(-dx * height, -dy * height, 1.0));
    float a = radians(angle);
    float3 l = normalize(float3(cos(a), -sin(a), 1.0));
    float diffuse = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), float3(0.0, 0.0, 1.0)), 0.0), 24.0) * shine;
    float3 base = float3(src.rgb) / float(src.a);
    float3 lit = base * float3(light.rgb) * (ambient + (1.0 - ambient) * diffuse / l.z) + float3(light.rgb) * spec;
    return half4(half3(clamp(lit, 0.0, 1.0)) * src.a, src.a);
}
